parameters.jsCode:
// Each LinkedIn alert holds several jobs separated by a line of dashes.
// Inside a block the order is: Title / Company / Location / View job: <url>,
// and after that come decorations ("3 connections", "Actively recruiting"...).
// That is why we count from the TOP: counting backwards from the link shifts the title.
const NOISE = [
  /^your job alert for/i,
  /^new jobs? match/i,
  /^\d+ new jobs? match/i,
  /^\d+\s+connections?$/i,
  /^\d+\s+(school\s+)?alum(ni)?\b/i,
  /^this company is actively hiring$/i,
  /^actively recruiting$/i,
  /^apply with resume/i,
  /^easy apply$/i,
  /^promoted$/i,
  /^viewed$/i,
  /^be an early applicant$/i,
];

const jobs = [];

for (const item of $input.all()) {
  const blocks = String(item.json.text || '').split(/\n-{10,}\n/);

  for (const block of blocks) {
    const lines = block.split('\n').map((l) => l.trim());
    const i = lines.findIndex((l) => l.startsWith('View job: '));
    if (i === -1) continue;

    const m = lines[i].match(/jobs\/view\/(\d+)/);
    if (!m) continue;

    const data = lines
      .slice(0, i)
      .filter((l) => l && !NOISE.some((re) => re.test(l)));
    if (data.length < 3) continue;

    const [title, company, place] = data;

    jobs.push({
      json: {
        title: title + ' — ' + company,
        // Clean link on purpose: the original carries tracking tokens that change
        // in every email, which would make the dedupe see the same job as new.
        link: 'https://www.linkedin.com/jobs/view/' + m[1],
        contentSnippet: 'Company: ' + company + '. Location: ' + place + '. Source: LinkedIn job alert.',
      },
    });
  }
}

return jobs;

// One item per search. The HTTP node downstream runs once per item,
// so three queries come out of a single node.
// Chosen after testing six: broad words returned mostly on-site local jobs.
// >>> REPLACE these with the terms of your own field.
return ['automation', 'healthcare', 'n8n'].map((q) => ({ json: { q } }));

// Normalizes Get on Board into the same fields as every other source.
// The 'region' field is what the scoring prompt already reads as WHERE THEY HIRE,
// so the scoring node needs no changes.
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  for (const j of item.json.data || []) {
    const a = j.attributes || {};
    const url = (j.links || {}).public_url;
    if (!url || seen.has(url)) continue;
    seen.add(url);

    const company = a.company?.data?.attributes?.name || '';
    const countries = Array.isArray(a.countries) ? a.countries.join(', ') : '';

    // fully_remote accepts any country; remote_local usually means one region;
    // hybrid and no_remote tie you to a city. Passed raw to the LLM with the country.
    const region = [a.remote_modality, countries].filter(Boolean).join(' — ') || 'unspecified';

    const salary = a.min_salary
      ? ' Published salary: ' + a.min_salary + '-' + (a.max_salary || a.min_salary) + ' USD per month.'
      : '';

    const text = [a.description, a.functions, a.desirable]
      .filter(Boolean).join(' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    out.push({
      json: {
        title: a.title + (company ? ' — ' + company : ''),
        link: url,
        region,
        contentSnippet: 'Source: Get on Board (LatAm).' + salary + ' ' + text.slice(0, 1200),
      },
    });
  }
}

return out;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "score": { "type": "integer", "minimum": 0, "maximum": 10, "description": "How well the job fits the profile" },
    "reason": { "type": "string", "description": "One short sentence explaining the score" },
    "keywords": { "type": "array", "items": { "type": "string" }, "description": "Up to 4 terms from the posting the CV should mirror" }
  },
  "required": ["score", "reason", "keywords"]
}
